//! Serum 2 parameter registry.
//!
//! - `data/serum2_schema.json`: modules, params (ids = Serum's enum ordinals, used as
//!   `destModuleParamID` in mod slots), value enums, and value ranges observed in the factory
//!   library. Generated by `tools/serum2_extract_schema.py` from the plugin binary + presets.
//! - [`MOD_SOURCES`]: mod-matrix source ids (`ModSlot{n}.source = [main, aux]`), taken from the
//!   ordered source-name table in the Serum 2.1.5 binary (id = table index + 1, 0 = none) and
//!   cross-checked against usage frequencies in the factory library.

use std::collections::BTreeMap;
use std::sync::OnceLock;

use serde::Deserialize;

/// Mod source names indexed by id. Id 0 is "None".
pub const MOD_SOURCES: [&str; 60] = [
    "None",
    "Mod Wheel",
    "Env 1",
    "Env 2",
    "Env 3",
    "Env 4",
    "LFO 1",
    "LFO 2",
    "LFO 3",
    "LFO 4",
    "LFO 5",
    "LFO 6",
    "LFO 7",
    "LFO 8",
    "LFO 9",
    "LFO 10",
    "Velo",
    "Note#",
    "Aftertouch",
    "Poly Aftertch",
    "Noise OSC",
    "NoteOn Rand1",
    "NoteOn Rand2",
    "NoteOn Alt.",
    "NoteOn Alt.2",
    "Macro 1",
    "Macro 2",
    "Macro 3",
    "Macro 4",
    "Macro 5",
    "Macro 6",
    "Macro 7",
    "Macro 8",
    "Pitch Bend",
    "Expr X (Pan)",
    "Expr Y (Timbre)",
    "Expr Z (Press.)",
    "Release Velo",
    "Fixed",
    "LFO 1 Y",
    "LFO 2 Y",
    "LFO 3 Y",
    "LFO 4 Y",
    "LFO 5 Y",
    "LFO 6 Y",
    "LFO 7 Y",
    "LFO 8 Y",
    "LFO 9 Y",
    "LFO 10 Y",
    "OSC A",
    "OSC B",
    "OSC C",
    "SUB OSC",
    "Filter 1",
    "Filter 2",
    "Active Voices",
    "Voice Mod 1",
    "Voice Mod 2",
    "Voice Index",
    "NoteOn Rand (Discrete)",
];

/// Resolve a source name (case/space-insensitive, e.g. "lfo1", "Macro 3", "velo") to its id.
pub fn mod_source_id(name: &str) -> Option<i64> {
    let norm = |s: &str| s.chars().filter(|c| c.is_ascii_alphanumeric()).collect::<String>().to_ascii_lowercase();
    let want = norm(name);
    MOD_SOURCES.iter().position(|s| norm(s) == want).map(|i| i as i64)
}

#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Schema {
    pub modules: BTreeMap<String, Module>,
    pub enums: BTreeMap<String, Vec<String>>,
    #[serde(default)]
    pub notes: Vec<String>,
}

#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Module {
    #[serde(default)]
    pub paths: Vec<String>,
    #[serde(default)]
    pub fx_type_id: Option<i64>,
    pub params: Vec<Param>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Param {
    pub name: String,
    pub id: Option<i64>,
    #[serde(default)]
    pub automatable: Option<bool>,
    #[serde(default, rename = "enum")]
    pub enum_name: Option<String>,
    #[serde(default)]
    pub observed: Option<Observed>,
}

#[derive(Debug, Clone, Default, Deserialize)]
pub struct Observed {
    #[serde(default)]
    pub count: u64,
    pub min: Option<f64>,
    pub max: Option<f64>,
    #[serde(default)]
    pub strings: Vec<String>,
}

static SCHEMA: OnceLock<Schema> = OnceLock::new();

/// The embedded Serum 2 schema.
pub fn schema() -> &'static Schema {
    SCHEMA.get_or_init(|| {
        let mut s: Schema =
            serde_json::from_str(include_str!("../data/serum2_schema.json")).expect("embedded serum2_schema.json is valid");
        // The binary's enum declarations end with count sentinels (`kNumOscTypes`, `kCount`);
        // those are not values Serum stores.
        for values in s.enums.values_mut() {
            values.retain(|v| v != "kCount" && !v.starts_with("kNum"));
        }
        s
    })
}

impl Schema {
    pub fn module(&self, module_type: &str) -> Option<&Module> {
        self.modules.get(module_type)
    }

    pub fn param(&self, module_type: &str, name: &str) -> Option<&Param> {
        self.module(module_type)?.params.iter().find(|p| p.name == name)
    }

    /// Allowed string values for an enum-typed param.
    pub fn enum_values(&self, param: &Param) -> Option<&[String]> {
        param.enum_name.as_deref().and_then(|e| self.enums.get(e)).map(Vec::as_slice)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn mod_source_lookup() {
        assert_eq!(mod_source_id("LFO 1"), Some(6));
        assert_eq!(mod_source_id("lfo10"), Some(15));
        assert_eq!(mod_source_id("macro 1"), Some(25));
        assert_eq!(mod_source_id("Velo"), Some(16));
        assert_eq!(mod_source_id("nope"), None);
    }

    #[test]
    fn schema_loads_and_has_core_modules() {
        let s = schema();
        for m in ["Oscillator", "WTOsc", "VoiceFilter", "Env", "LFO", "Macro", "Global", "ModSlot"] {
            assert!(s.module(m).is_some(), "missing module {m}");
        }
        assert!(s.param("VoiceFilter", "kParamFreq").is_some());
    }
}
